update public.chambers
set pupillage_overview='Keating normally offers up to two funded 12-month pupillages each year through the Pupillage Gateway. The current published award is £90,000, with up to £30,000 available as an advance for Bar Course fees or other expenses. Recruitment consists of a Gateway application, written case study and two interview rounds. Pupils rotate through four supervisors and receive specialist commercial training.',
    mini_pupillage_overview='Keating offers approximately 50 unassessed one-day mini-pupillages each year. Applicants must be in the final year of a law degree, undertaking the GDL or beyond. Applications for July to September placements close on 31 March and applications for November to January placements close on 1 September. Reasonable receipted expenses are reimbursed, and a virtual group placement can be requested.',
    research_status='verified',research_checked_on=date '2026-10-15',
    next_review_on=date '2026-11-23',updated_at=now()
where organisation_id='78bfc832-5e9c-4d48-a287-646290269709';

