values
  ('51a9940e-1fa2-40dd-b888-75dd9b253fd7','78bfc832-5e9c-4d48-a287-646290269709','b29890c7-5f97-4d55-bbf8-9e7fda5e22b3','keating-combar-mentoring-2026-27','COMBAR Mentoring Scheme 2026–27 — Keating Chambers Partner','COMBAR Mentoring Scheme 2026–27 — Keating Chambers Partner','One-to-one mentoring for aspiring barristers from groups underrepresented at the Bar, delivered by practitioners from participating COMBAR member sets including Keating Chambers.','hybrid','https://www.combar.com/news/deadline-extended-to-23-october-2026-combar-mentoring-scheme-for-under-represented-groups-2026-27-scheme/','https://www.combar.com/news/deadline-extended-to-23-october-2026-combar-mentoring-scheme-for-under-represented-groups-2026-27-scheme/',true,true,500,date '2026-10-15',date '2026-10-24',now(),now(),false),
  ('19036058-f62e-4a33-8d9d-e3afad2059be','78bfc832-5e9c-4d48-a287-646290269709','06f22221-7e57-4379-b2a1-fcbec5d4f4bb','keating-10000-black-interns-bar-2027','10,000 Black Interns — The Bar 2027 — Keating Chambers Partner','10,000 Black Interns — The Bar 2027 — Keating Chambers Partner','Paid six-week Bar internship programme for eligible Black students and recent graduates. Keating Chambers confirms that it supports interns through the programme.','in_person','https://10000internsfoundation.com/students-graduates/10000-black-interns/','https://10000internsfoundation.com/students-graduates/10000-black-interns/',true,true,500,date '2026-10-15',date '2026-11-02',now(),now(),false);

